  "implementation": "def solve(case):
    threshold = case['threshold']
    calls = case['calls']
    retained = []
    total_tokens = sum(c['prediction_tokens'] for c in calls if c['parseable'])
    if total_tokens == 0:
        return []
    for c in calls:
        if not c['parseable']:
            continue
        benefit = c['loss_without_call'] - c['loss_with_call']
        # Normalize benefit by future-token weight (proportion of total tokens)
        weight = c['prediction_tokens'] / total_tokens
        normalized_benefit = benefit * weight
        # Use the stronger counterfactual: benefit > 0 already assumes loss_without_call > loss_with_call
        if normalized_benefit >= threshold:
            retained.append(c['call_id'])
    return retained"
